#!/usr/bin/env node
// Strips the bloated `spec.info.description` injected by openapi-generator
// into the JSDoc header of every generated .ts file. Replaces the first
// JSDoc block with a minimal one that keeps only the OpenAPI Generator
// boilerplate (version + auto-generated notice).
//
// Run after every regeneration: `node scripts/strip-spec-description.mjs`.
import { readdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

const ROOT = fileURLToPath(new URL("../src/", import.meta.url));

const MINIMAL_HEADER = `/* tslint:disable */
/* eslint-disable */
/**
 * SOPHON Encoding API
 *
 * NOTE: This class is auto generated by OpenAPI Generator (https://openapi-generator.tech).
 * https://openapi-generator.tech
 * Do not edit the class manually.
 */
`;

const HEADER_RE =
  /^\/\* tslint:disable \*\/\r?\n\/\* eslint-disable \*\/\r?\n\/\*\*[\s\S]*?\* Do not edit the class manually\.\r?\n \*\/\r?\n/;

async function* walk(dir) {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(path);
    else if (entry.name.endsWith(".ts")) yield path;
  }
}

let touched = 0;
let skipped = 0;
for await (const file of walk(ROOT)) {
  const src = await readFile(file, "utf8");
  if (!HEADER_RE.test(src)) {
    skipped++;
    continue;
  }
  const out = src.replace(HEADER_RE, MINIMAL_HEADER);
  if (out !== src) {
    await writeFile(file, out, "utf8");
    touched++;
  }
}
console.log(`strip-spec-description: rewrote ${touched} file(s), skipped ${skipped}.`);
